mapper.delete:
DELETE FROM board

WHERE board_id = #{boardId}
  AND board_type = 'NOTICE'

mapper.select:
SELECT COUNT(*) FROM board b JOIN member m ON b.member_id = m.member_id
AND b.board_type = #{boardType}
AND b.board_type != 'NOTICE'
AND b.board_type = #{boardType}
AND b.member_id = #{memberId}
AND m.nickname LIKE CONCAT('%', #{keyword}, '%')
AND b.title LIKE CONCAT('%', #{keyword}, '%')
AND b.content LIKE CONCAT('%', #{keyword}, '%')
AND ( b.title LIKE CONCAT('%', #{keyword}, '%') OR b.content LIKE CONCAT('%', #{keyword}, '%') )

mapper.update:
UPDATE board
SET board_type = #{boardType}, title = #{title}, content = #{content}, updated_at = NOW()
WHERE board_id = #{boardId} AND member_id = #{memberId}

mapper.delete:
DELETE FROM board
WHERE board_id = #{boardId}
    AND member_id = #{memberId}
